import re
from pathlib import Path
L=Path('candidate/statement-ledger.md').read_text().splitlines(); sec=None; cats={}; pairs=set(); ip=set(); nd=[]
for n,l in enumerate(L,1):
 m=re.match(r'## (\\w+) \\((.*)\\)"'$'"',l)
 if m:sec=m[1];cats[sec]=next(c for c in ['whole result','narrower results','narrower result','foundation','proof steps'] if m[2].startswith(c))
 if l.startswith('| ') and sec and n>700:
  cs=re.split(r'(?<"'!'"\\\\)\\|',l)[1:-1]
  if len(cs)==4:
   labs=re.findall(r'"'`([A-Z][A-Za-z]*:[''^`'"\\s]+)"'`'"',cs[0])
   if cs[0].strip().startswith('no direct label') and labs:nd.append(n)
   for lab in labs or ['no direct label']: pairs.add((lab,sec))
for n,l in enumerate(L,1):
 if 505<n<700 and l.startswith('| '):
  cs=l.split('|');lab=cs[1].strip().strip('"'`'"')
  for s,c in re.findall(r'"'`('"\\w+)"'` '"\\(([a-z ]+)\\)',cs[2]):
   ip.add((lab,s))
   if cats.get(s)"'!=c:print('"'CATEGORY ERROR',n,s,c,cats.get(s))
print('Independent pointer set comparison:',len(pairs),len(ip),'missing',sorted(pairs-ip),'extra',sorted(ip-pairs),'labels in no-direct cells',nd)
